#include "phase6_test.hpp"
#include "oms/order_state.hpp"
int main(){Phase6Test t;for(int a=0;a<12;++a)for(int b=0;b<12;++b){auto x=static_cast<exec::OrderState>(a),y=static_cast<exec::OrderState>(b);bool expected=(a==0&&(b==1||b==2))||(a==2&&b==3)||(a==3&&(b==4||b==5||b==6))||(a==4&&(b==7||b==8||b==9||b==11))||(a==7&&(b==7||b==8||b==9))||(a==9&&(b==10||b==8||b==6))||(a==6&&exec::is_terminal(y));t.check(oms::legal(x,y)==expected,"order transition matrix");}for(int a=0;a<12;++a)if(exec::is_terminal(static_cast<exec::OrderState>(a)))for(int b=0;b<12;++b)t.check(!oms::legal(static_cast<exec::OrderState>(a),static_cast<exec::OrderState>(b)),"terminal closed");for(int b=0;b<12;++b)t.check(oms::legal(exec::OrderState::unknown,static_cast<exec::OrderState>(b))==exec::is_terminal(static_cast<exec::OrderState>(b)),"unknown only terminal");return t.result();}
